import type { Metadata } from "next";
import { ToastProvider } from "@/components/ui/Toast/Toast";
import { inter } from "./fonts";
import { ThemeScript } from "./ThemeScript";
import "./globals.css";

export const metadata: Metadata = {
  title: { default: "Acme", template: "%s · Acme" },
  description: "Built with Rime.",
};

export default function RootLayout({ children }: { children: React.ReactNode }) {
  return (
    <html lang="en" className={inter.variable} suppressHydrationWarning>
      <head>
        <ThemeScript />
      </head>
      <body>
        <ToastProvider>{children}</ToastProvider>
      </body>
    </html>
  );
}

// Sets the Rime preset and colour mode on <html> before first paint, so a
// reload never flashes the wrong theme. Preset: data-theme="flat" for Rime
// Flat (nothing for Rime Default). Mode: the .dark class plus
// data-mode="dark", from the stored choice or the system setting.
// Store "flat" in localStorage "rime-preset" and "light" or "dark" in
// "rime-mode" to change them.

const SCRIPT = `try{var d=document.documentElement,p=localStorage.getItem("rime-preset"),m=localStorage.getItem("rime-mode");if(p==="flat")d.setAttribute("data-theme","flat");if(m!=="light"&&m!=="dark")m=matchMedia("(prefers-color-scheme: dark)").matches?"dark":"light";if(m==="dark"){d.classList.add("dark");d.setAttribute("data-mode","dark")}d.style.colorScheme=m}catch(e){}`;

export function ThemeScript() {
  return <script dangerouslySetInnerHTML={{ __html: SCRIPT }} />;
}

import localFont from "next/font/local";

// Inter, self-hosted (SIL Open Font License), so the app builds offline.
// Rime's tokens point --font-body and --font-display at --font-inter.
export const inter = localFont({
  src: "./fonts/inter-latin-100-900-normal.woff2",
  weight: "100 900",
  variable: "--font-inter",
  display: "swap",
});

/* Rime first (installed by the shadcn CLI), then your theme. */
@import "./styles/tokens.css";
@import "./styles/base.css";
@import "./styles/shadcn-bridge.css";
@import "./styles/theme.css";

/* Acme's theme: only what differs from Rime Default.
   Make one in Rime Studio (https://rime.mjsons.net/themes): start from a
   preset, drop in your logo to extract a palette, check contrast in light
   and dark, then Export and paste the result here. For example:

   :root {
     --brand: #0f9b8e;
     --brand-action: #0b7a70;
     --brand-strong: #075f57;
     --rgb-brand: 15, 155, 142;
     --r-md: 6px;
   }

   .dark, [data-mode="dark"] {
     --brand: #3fc6b8;
     --rgb-brand: 63, 198, 184;
   }

   Load it after the Rime styles (app/globals.css does). Never edit
   tokens.css itself: re-running the CLI would overwrite it. */

